import{z as n,x as d,o as E,c as B,q as r,j as o,D as e,d as t,s as i,S as A,b as s}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"shuffle 与 broadcast join","description":"","frontmatter":{"title":"shuffle 与 broadcast join","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/distributed-join-shuffle.md","filePath":"cs/distributed-join-shuffle.md","lastUpdated":1791413859000}'),f={name:"cs/distributed-join-shuffle.md"};function h(u,a,p,c,b,D){const l=d("Mermaid");return E(),B("div",null,[a[2]||(a[2]=r('<h1 id="shuffle-与-broadcast-join" tabindex="-1">shuffle 与 broadcast join <a class="header-anchor" href="#shuffle-与-broadcast-join" aria-label="Permalink to &quot;shuffle 与 broadcast join&quot;">​</a></h1><div class="epigraph"><p>等值连接在分片上要让同键碰面：shuffle 按键重分区，broadcast 把小侧复制到每一片。网络字节是代价模型的新项。</p><footer>—— 据 Graefe exchange；DeWitt 并行连接；分布式 Grace 同构</footer></div><p><a href="/cs/shard-key-rebalance">上一课</a>把行放在片上。本课不选用户 id。缺口是连接：若两表已按连接键同切（collocated），工人本地连，无网络。否则要 <a href="/cs/parallel-exchange">exchange</a> 的网络版：shuffle join 或 broadcast join。单机 Grace 的分区文件换成网络块。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>大对大：两边按连接键 hash 送到 \\(N\\) 个工人，正确性同 Grace。小对大：广播小表，大表本地扫，避免动大表。缺口是估计：小表估错会变成广播一张大表打爆内存——基数误差的分布式形态。倾斜：单键打到一工人，同单机倾斜。</p><p>半连接归约：先传键再拉匹配行，Bernstein-Chiu 思想，减 payload。延迟物化：只 shuffle 键+位置，载荷留在存储节点——存算分离后课。</p><p><span class="marginnote">并行数据库教科书连接。Spark shuffle 是同一算子在批处理引擎。本课数据库执行器。</span></p><p><span class="marginnote">数字实例看 broadcast 的代价模型：小表 10 MB、200 个工人，广播要发 \\(10\\text{ MB}\\times200=2\\) GB 进网络，换回大表一次不动；若优化器把小表估成 10 MB 实际是 50 GB，广播就成了 10 TB 的灾难——「估错小表」在这里被网络放大 200 倍，这正是基数估计直接决定计划生死的原因。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>优化器比较：colocated \\(\\lt\\) broadcast \\(\\lt\\) shuffle（通常）。强制提示可钉。bloom 过滤器随广播或 shuffle 前过滤。外连接：broadcast 方向受限（只能广播被保留侧的对面等），与外连接下推防火墙同类。</p>',10)),(E(),o(A,null,{default:e(()=>[i(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20COL%5B%22%E5%90%8C%E9%94%AE%E5%90%8C%E5%88%87%22%5D%20--%3E%20LOC%5B%22%E6%9C%AC%E5%9C%B0%E8%BF%9E%E6%8E%A5%22%5D%0A%20%20SMALL%5B%22%E5%B0%8F%E8%A1%A8%22%5D%20--%3E%20BC%5B%22%E5%B9%BF%E6%92%AD%E5%88%B0%E5%90%84%E5%A4%A7%E8%A1%A8%E7%89%87%22%5D%0A%20%20BIG%5B%22%E4%B8%A4%E8%A1%A8%E9%83%BD%E5%A4%A7%22%5D%20--%3E%20SH%5B%22%E6%8C%89%E9%94%AE%20shuffle%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s("h2",{id:"机制",tabindex:"-1"},[t("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=s("p",null,"RTO 无关；这是查询时流量。计划回归：统计变化让昨日 colocated 今日 shuffle。网络校准必须进代价模型，否则 DP 以为哈希内存连接免费。bloom 随广播或 shuffle 前过滤，减 payload，思想同 LSM 布隆但走的是连接键。",-1)),a[5]||(a[5]=s("p",null,"事务：分布式连接一般读快照，写仍按分片事务。连接本身不提交两片写。外连接限制 broadcast 方向。倾斜使某一工人收到大部分键，并行名存实亡——要拆热键或加盐，与单机 Grace 相同病。",-1)),(E(),o(A,null,{default:e(()=>[i(l,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20RAW%5B%22%E5%8E%9F%E5%A7%8B%E6%8C%89%E9%94%AE%20shuffle%EF%BC%9A%E9%94%AE%20user_1%20%E5%8D%A0%2090%25%20%E8%A1%8C%22%5D%0A%20%20%20%20K1%5B%22user_1%20%E7%9A%84%209000%20%E4%B8%87%E8%A1%8C%22%5D%20--%3E%20W0%5B%22%E5%B7%A5%E4%BA%BA%200%EF%BC%9A%E8%A2%AB%E5%8E%8B%E5%9E%AE%22%5D%0A%20%20%20%20K2%5B%22%E5%85%B6%E4%BD%99%E9%94%AE%E5%90%88%E8%AE%A1%201000%20%E4%B8%87%E8%A1%8C%22%5D%20--%3E%20W1%5B%22%E5%B7%A5%E4%BA%BA%201%E2%80%93199%EF%BC%9A%E9%97%B2%E7%9D%80%22%5D%0A%20%20end%0A%20%20subgraph%20SALT%5B%22%E5%8A%A0%E7%9B%90%E5%90%8E%EF%BC%9A%E7%83%AD%E9%94%AE%E6%8B%86%208%20%E4%BB%BD%22%5D%0A%20%20%20%20S1%5B%22user_1%230%20%E2%80%A6%20user_1%237%20%E5%90%84%E7%BA%A6%201125%20%E4%B8%87%E8%A1%8C%22%5D%20--%3E%20W2%5B%22%E5%B7%A5%E4%BA%BA%200%E2%80%937%EF%BC%9A%E5%9D%87%E5%8C%80%22%5D%0A%20%20%20%20S3%5B%22%E5%85%B6%E4%BD%99%E9%94%AE%E7%85%A7%E6%97%A7%22%5D%20--%3E%20W3%5B%22%E5%B7%A5%E4%BA%BA%208%E2%80%93199%22%5D%0A%20%20%20%20S2%5B%22join%20%E9%94%AE%E6%8B%BC%E4%B8%8A%E9%9A%8F%E6%9C%BA%E5%90%8E%E7%BC%80%EF%BC%8C%E4%B8%A4%E4%BE%A7%E5%90%8C%E8%A7%84%E5%88%99%22%5D%20-.-%3E%20S1%0A%20%20end%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p>这张图回答「倾斜怎么让并行名存实亡、加盐怎么救」：hash 只认键，不认键的流行度——一个顶流 user 的行全部涌向同一个工人，199 台机器围观一台干活。加盐把热键拼上随机后缀拆成多份分摊，代价是连接条件要两侧都按同一规则改写，且聚合要再来一轮合并。</p><p><span class="marginnote">术语翻译：shuffle（洗牌）就是连接前的「重新分堆」——每行按连接键的哈希值决定去几号工人，保证同键的行必然落进同一堆，两边才能就地连接。它回答的是「让谁和谁碰面」，网络字节数就是这次碰面的路费。</span></p><p><span class="marginnote">常见误区：初学者容易以为「工人加一倍，连接就快一倍」。shuffle 阶段的网络流量近似随工人数平方级增长（\\(N\\) 个工人各向 \\(N\\) 个工人发），而倾斜键又卡死单点——并行度上限由最热的那个键决定。先看键分布再谈加机器，否则只是花钱把瓶颈挪个地方。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 Percolator 锁。也不把 MapReduce shuffle 当 SQL 连接的定义——后课 MR 是另一套。图遍历的多跳 shuffle 更重，图库课。</p><p>后课默认：跨片等值连接靠 colocated / broadcast / shuffle 三选。Percolator：在 Bigtable 上用锁表做跨行事务。</p><p>网络是第二磁盘。估错大小等于估错 I/O。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>同切本地连；否则广播小表或按键 shuffle。</li><li>倾斜与估错会打爆单工人。</li><li>Percolator 下一课：宽列上的分布式事务。</li><li>出处：Graefe；DeWitt；Bernstein-Chiu 半连接。</li></ul>',9))])}const _=n(f,[["render",h]]);export{C as __pageData,_ as default};
